/**
 * Unit tests for share-token.ts — HMAC sign/verify, canonical serialization.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";

// Must be declared before importing the module under test so vi.stubEnv
// applies at module init time (tested separately via dynamic import).

describe("share-token", () => {
  const SECRET = "test-secret-32-bytes-0000000000000";

  beforeEach(() => {
    vi.stubEnv("RUNWAY_SHARE_SECRET", SECRET);
  });

  afterEach(() => {
    vi.unstubAllEnvs();
  });

  // Helpers imported after env is stubbed.
  async function getModule() {
    const mod = await import("./share-token");
    return mod;
  }

  it("signPayload produces a token with exactly one '.' separator", async () => {
    const { signPayload, makePayload } = await getModule();
    const payload = makePayload({
      kind: "client",
      clientSlug: "test-client",
      theme: "light-branded",
    });
    const token = signPayload(payload);
    const parts = token.split(".");
    expect(parts).toHaveLength(2);
  });

  it("verifyToken round-trips payload exactly", async () => {
    const { signPayload, verifyToken, makePayload } = await getModule();
    const payload = makePayload({
      kind: "client",
      clientSlug: "test-client",
      theme: "light-branded",
    });
    const token = signPayload(payload);
    const result = verifyToken(token);
    expect(result.ok).toBe(true);
    if (!result.ok) throw new Error("unreachable");
    expect(result.payload.kind).toBe("client");
    expect(result.payload.clientSlug).toBe("test-client");
    expect(result.payload.theme).toBe("light-branded");
    expect(result.payload.v).toBe(1);
  });

  it("verifyToken returns malformed for a plain string without dot", async () => {
    const { verifyToken } = await getModule();
    const result = verifyToken("not-a-token");
    expect(result.ok).toBe(false);
    if (result.ok) throw new Error("unreachable");
    expect(result.reason).toBe("malformed");
  });

  it("verifyToken returns malformed for 3-part token", async () => {
    const { verifyToken } = await getModule();
    const result = verifyToken("a.b.c");
    expect(result.ok).toBe(false);
    if (result.ok) throw new Error("unreachable");
    expect(result.reason).toBe("malformed");
  });

  it("verifyToken returns malformed for invalid base64url characters", async () => {
    const { verifyToken } = await getModule();
    // Two parts but the payload contains invalid base64 chars
    const result = verifyToken("!invalid!base64!.!sig!");
    expect(result.ok).toBe(false);
    if (result.ok) throw new Error("unreachable");
    expect(result.reason).toBe("malformed");
  });

  it("verifyToken returns bad-signature when payload is tampered", async () => {
    const { signPayload, verifyToken, makePayload } = await getModule();
    const payload = makePayload({
      kind: "client",
      clientSlug: "test-client",
      theme: "light-branded",
    });
    const token = signPayload(payload);
    const [encodedPayload, sig] = token.split(".");
    // Decode, mutate, re-encode
    const decoded = Buffer.from(encodedPayload, "base64url").toString("utf8");
    const mutated = decoded.replace("test-client", "evil-client");
    const tamperedPayload = Buffer.from(mutated).toString("base64url");
    const result = verifyToken(`${tamperedPayload}.${sig}`);
    expect(result.ok).toBe(false);
    if (result.ok) throw new Error("unreachable");
    expect(result.reason).toBe("bad-signature");
  });

  it("verifyToken returns bad-signature when signature is tampered", async () => {
    const { signPayload, verifyToken, makePayload } = await getModule();
    const payload = makePayload({
      kind: "client",
      clientSlug: "test-client",
      theme: "light-branded",
    });
    const token = signPayload(payload);
    const [encodedPayload] = token.split(".");
    // Replace sig with garbage of the same approximate length
    const tamperedSig = Buffer.alloc(32).fill(0xff).toString("base64url");
    const result = verifyToken(`${encodedPayload}.${tamperedSig}`);
    expect(result.ok).toBe(false);
    if (result.ok) throw new Error("unreachable");
    expect(result.reason).toBe("bad-signature");
  });

  it("verifyToken returns expired for a token with past expiresAt", async () => {
    const { signPayload, verifyToken, makePayload } = await getModule();
    const payload = makePayload({
      kind: "client",
      clientSlug: "test-client",
      theme: "light-branded",
      ttlDays: -1, // already expired
    });
    const token = signPayload(payload);
    const result = verifyToken(token);
    expect(result.ok).toBe(false);
    if (result.ok) throw new Error("unreachable");
    expect(result.reason).toBe("expired");
  });

  it("verifyToken returns bad-version when v !== 1", async () => {
    const { signPayload, verifyToken } = await getModule();
    // Craft a payload with v: 2 directly, bypassing makePayload
    const badPayload = {
      v: 2,
      kind: "client" as const,
      clientSlug: "x",
      theme: "light-branded" as const,
      generatedAt: new Date().toISOString(),
      expiresAt: new Date(Date.now() + 86400_000).toISOString(),
      nonce: "abcdefgh",
    };
    // We need to sign it as a raw payload (cast to any to bypass type guard)
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const token = signPayload(badPayload as any);
    const result = verifyToken(token);
    expect(result.ok).toBe(false);
    if (result.ok) throw new Error("unreachable");
    expect(result.reason).toBe("bad-version");
  });

  it("signPayload throws when RUNWAY_SHARE_SECRET is not set", async () => {
    vi.unstubAllEnvs();
    vi.stubEnv("RUNWAY_SHARE_SECRET", "");
    // Dynamic import to get a fresh module without cached env
    const { makePayload } = await import("./share-token");
    const payload = makePayload({ kind: "client", clientSlug: "x", theme: "light-branded" });
    // Re-import fresh
    vi.resetModules();
    vi.stubEnv("RUNWAY_SHARE_SECRET", "");
    const freshMod = await import("./share-token");
    expect(() => freshMod.signPayload(payload)).toThrow("RUNWAY_SHARE_SECRET");
  });
});

/**
 * Gantt share-token — sign and verify short-lived HMAC tokens.
 *
 * Token format: base64url(canonicalPayloadJSON) + "." + base64url(hmacSha256)
 *
 * The canonical payload is JSON.stringify over an alphabetically-sorted key
 * object (`canonicalStringify`). This ensures the HMAC is computed over a
 * deterministic byte sequence regardless of insertion order.
 *
 * Secret: process.env.RUNWAY_SHARE_SECRET (required at call time; throws if absent).
 * Generate: openssl rand -hex 32
 */

import crypto from "crypto";
import type { Theme } from "./types";

// ── SharePayload ─────────────────────────────────────────

export type SharePayload = {
  v: 1;
  kind: "client" | "project";
  clientSlug: string;
  projectSlug?: string;
  theme: Theme;
  generatedAt: string; // ISO 8601
  expiresAt: string;   // ISO 8601
  nonce: string;       // 8 random base64url chars; R2 key collision avoidance
};

// ── Canonical serialization ───────────────────────────────

/**
 * JSON.stringify with alphabetically sorted keys for deterministic HMAC input.
 */
export function canonicalStringify(obj: unknown): string {
  if (obj === null || typeof obj !== "object" || Array.isArray(obj)) {
    return JSON.stringify(obj);
  }
  const sorted = Object.fromEntries(
    Object.entries(obj as Record<string, unknown>)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([k, v]) => [k, typeof v === "object" && v !== null ? JSON.parse(canonicalStringify(v)) : v]),
  );
  return JSON.stringify(sorted);
}

// ── HMAC helpers ──────────────────────────────────────────

function getSecret(): Buffer {
  const secret = process.env.RUNWAY_SHARE_SECRET;
  if (!secret) {
    throw new Error(
      "RUNWAY_SHARE_SECRET not configured. Set it in .env.local. Generate with: openssl rand -hex 32",
    );
  }
  return Buffer.from(secret, "utf8");
}

function computeHmac(canonicalBytes: Buffer, secret: Buffer): Buffer {
  return crypto.createHmac("sha256", secret).update(canonicalBytes).digest();
}

// ── makePayload helper ────────────────────────────────────

/**
 * Build a SharePayload with generated timestamps and nonce.
 */
export function makePayload(opts: {
  kind: "client" | "project";
  clientSlug: string;
  projectSlug?: string;
  theme: Theme;
  ttlDays?: number;
}): SharePayload {
  const ttl = opts.ttlDays ?? 7;
  return {
    v: 1,
    kind: opts.kind,
    clientSlug: opts.clientSlug,
    ...(opts.projectSlug ? { projectSlug: opts.projectSlug } : {}),
    theme: opts.theme,
    generatedAt: new Date().toISOString(),
    expiresAt: new Date(Date.now() + ttl * 86400_000).toISOString(),
    nonce: crypto.randomBytes(6).toString("base64url"),
  };
}

// ── signPayload ───────────────────────────────────────────

/**
 * Sign a SharePayload and return a URL-safe token string.
 * Throws if RUNWAY_SHARE_SECRET is not set.
 */
export function signPayload(payload: SharePayload): string {
  const secret = getSecret();
  const canonical = canonicalStringify(payload);
  const canonicalBytes = Buffer.from(canonical, "utf8");
  const sig = computeHmac(canonicalBytes, secret);

  const encodedPayload = canonicalBytes.toString("base64url");
  const encodedSig = sig.toString("base64url");
  return `${encodedPayload}.${encodedSig}`;
}

// ── verifyToken ───────────────────────────────────────────

export type VerifyOk = { ok: true; payload: SharePayload };
export type VerifyFail = {
  ok: false;
  reason: "malformed" | "bad-signature" | "expired" | "bad-version";
};
export type VerifyResult = VerifyOk | VerifyFail;

const VALID_THEMES: Set<string> = new Set<Theme>(["light-internal", "light-branded", "dark-account-view"]);
const VALID_KINDS: Set<string> = new Set(["client", "project"]);

function isValidPayloadShape(obj: unknown): obj is SharePayload {
  if (typeof obj !== "object" || obj === null) return false;
  const p = obj as Record<string, unknown>;
  if (typeof p.clientSlug !== "string") return false;
  if (typeof p.kind !== "string" || !VALID_KINDS.has(p.kind)) return false;
  if (typeof p.theme !== "string" || !VALID_THEMES.has(p.theme)) return false;
  if (typeof p.generatedAt !== "string" || isNaN(Date.parse(p.generatedAt))) return false;
  if (typeof p.expiresAt !== "string" || isNaN(Date.parse(p.expiresAt))) return false;
  if (typeof p.nonce !== "string") return false;
  return true;
}

/**
 * Verify a Gantt share token. Returns the payload on success or a typed error.
 *
 * Steps:
 * 1. Split on '.'. Exactly 2 parts required.
 * 2. base64url-decode both parts.
 * 3. Recompute HMAC. Use timingSafeEqual (padded to same length) to avoid timing leaks.
 * 4. JSON.parse and validate shape. v !== 1 → bad-version.
 * 5. Check expiry.
 */
export function verifyToken(token: string): VerifyResult {
  const parts = token.split(".");
  if (parts.length !== 2) {
    return { ok: false, reason: "malformed" };
  }

  const [encodedPayload, encodedSig] = parts;

  let payloadBytes: Buffer;
  let sigBytes: Buffer;
  try {
    payloadBytes = Buffer.from(encodedPayload, "base64url");
    sigBytes = Buffer.from(encodedSig, "base64url");
    // Validate that re-encoding matches (catches garbage base64 strings)
    if (payloadBytes.toString("base64url") !== encodedPayload) {
      return { ok: false, reason: "malformed" };
    }
    if (sigBytes.toString("base64url") !== encodedSig) {
      return { ok: false, reason: "malformed" };
    }
  } catch {
    return { ok: false, reason: "malformed" };
  }

  // Verify HMAC
  let secret: Buffer;
  try {
    secret = getSecret();
  } catch {
    // RUNWAY_SHARE_SECRET not configured — treat as bad-signature at verify time
    return { ok: false, reason: "malformed" };
  }

  const expectedSig = computeHmac(payloadBytes, secret);

  // Timing-safe comparison: pad both to the same length to avoid length leaks
  const maxLen = Math.max(sigBytes.length, expectedSig.length);
  const a = Buffer.alloc(maxLen);
  const b = Buffer.alloc(maxLen);
  sigBytes.copy(a);
  expectedSig.copy(b);

  let sigsMatch = false;
  try {
    sigsMatch = crypto.timingSafeEqual(a, b);
  } catch {
    return { ok: false, reason: "bad-signature" };
  }

  if (!sigsMatch) {
    return { ok: false, reason: "bad-signature" };
  }

  // Parse payload
  let parsed: unknown;
  try {
    parsed = JSON.parse(payloadBytes.toString("utf8"));
  } catch {
    return { ok: false, reason: "malformed" };
  }

  if (typeof parsed !== "object" || parsed === null) {
    return { ok: false, reason: "malformed" };
  }

  const p = parsed as Record<string, unknown>;

  // Version check
  if (p.v !== 1) {
    return { ok: false, reason: "bad-version" };
  }

  // Shape validation
  if (!isValidPayloadShape(parsed)) {
    return { ok: false, reason: "malformed" };
  }

  // Expiry check
  if (Date.parse(parsed.expiresAt) <= Date.now()) {
    return { ok: false, reason: "expired" };
  }

  return { ok: true, payload: parsed };
}

/**
 * Gantt share server module — generateGanttShare() and supporting resolvers.
 *
 * This module is the src/-side equivalent of scripts/lib/gantt/{resolve-entity,
 * extract-data, rundown}.ts. It authors fresh async DB-coupled wrappers that
 * use the same pure helpers from src/lib/runway/gantt/* so both paths are
 * byte-equivalent by construction.
 *
 * Do NOT import from scripts/lib/gantt/ here — scripts/ is operator-locked
 * until Phase D. Use @/lib/runway/gantt/* aliases for pure helpers.
 */

import crypto from "crypto";
import { and, eq, inArray, isNull } from "drizzle-orm";
import { getRunwayDb } from "@/lib/db/runway";
import {
  clients,
  projects as projectsTable,
  weekItems,
} from "@/lib/db/runway-schema";
import { uploadContent } from "@/lib/storage/r2-client";
import {
  classifyProject,
  resolveClientFromList,
  resolveProjectFromList,
} from "@/lib/runway/gantt/resolve-helpers";
import { buildRawData } from "@/lib/runway/gantt/build-raw-data";
import {
  detectChildProjectIssues,
} from "@/lib/runway/gantt/detect-issues";
import {
  addSeverity,
  buildL1SectionData,
  buildWrapperSectionData,
  slugAnchor,
} from "@/lib/runway/gantt/section-builders";
import {
  renderGantt,
  renderClientRundown,
} from "@/lib/runway/gantt/GanttTemplate";
import { makePayload, signPayload } from "@/lib/runway/gantt/share-token";
import type {
  ClientRow,
  ClientRundownData,
  ProjectRow,
  RawData,
  ResolveClientResult,
  ResolveProjectResult,
  ResolvedSubject,
  RundownSection,
  SeverityCounts,
  WeekItemRow,
} from "@/lib/runway/gantt/types";
import type { Theme } from "@/lib/runway/gantt/types";

// ── R2 config check ───────────────────────────────────────

function isR2Configured(): boolean {
  return !!(
    process.env.R2_ACCOUNT_ID &&
    process.env.R2_ACCESS_KEY_ID &&
    process.env.R2_SECRET_ACCESS_KEY &&
    process.env.R2_BUCKET_NAME
  );
}

// ── DB type alias ──────────────────────────────────────────

type DrizzleDb = ReturnType<typeof getRunwayDb>;

// ── Async resolvers (src/-side, mirrors scripts/lib/gantt/) ──

export async function resolveClient(
  db: DrizzleDb,
  input: string,
): Promise<ResolveClientResult> {
  const allClients = await db.select().from(clients);
  const result = resolveClientFromList(allClients, input);
  if (!result.ok) return result;

  const topLevelProjects = await db
    .select()
    .from(projectsTable)
    .where(
      and(
        eq(projectsTable.clientId, result.client.id),
        isNull(projectsTable.parentProjectId),
      ),
    );

  return { ok: true, client: result.client, topLevelProjects };
}

export async function resolveProject(
  db: DrizzleDb,
  input: string,
): Promise<ResolveProjectResult> {
  const [allClients, allProjects] = await Promise.all([
    db.select().from(clients),
    db.select().from(projectsTable),
  ]);
  const clientsById = new Map(allClients.map((c) => [c.id, c]));

  const result = resolveProjectFromList(allProjects, clientsById, input);
  if (!result.ok) return result;

  const childProjects = allProjects.filter(
    (p) => p.parentProjectId === result.project.id,
  );
  return { ok: true, subject: classifyProject(result.project, childProjects) };
}

export async function extractData(
  db: DrizzleDb,
  subject: ResolvedSubject,
  client: ClientRow,
): Promise<RawData> {
  const items = await db
    .select()
    .from(weekItems)
    .where(eq(weekItems.projectId, subject.project.id));
  return buildRawData(subject, client, items);
}

const ZERO: SeverityCounts = { critical: 0, warn: 0, info: 0 };

export async function extractClientRundown(
  db: DrizzleDb,
  client: ClientRow,
  topLevelProjects: ProjectRow[],
  generatedAt: string,
  todayISO: string,
): Promise<ClientRundownData> {
  type ClassifiedTop =
    | { kind: "wrapper"; project: ProjectRow; children: ProjectRow[] }
    | { kind: "standalone"; project: ProjectRow };

  const classified: ClassifiedTop[] = [];
  for (const top of topLevelProjects) {
    const children = await db
      .select()
      .from(projectsTable)
      .where(eq(projectsTable.parentProjectId, top.id));
    if (
      top.parentProjectId === null &&
      top.engagementType === "retainer" &&
      children.length > 0
    ) {
      classified.push({ kind: "wrapper", project: top, children });
    } else {
      classified.push({ kind: "standalone", project: top });
    }
  }

  const idsNeedingWeekItems = new Set<string>();
  for (const c of classified) {
    if (c.kind === "wrapper") {
      idsNeedingWeekItems.add(c.project.id);
      for (const child of c.children) idsNeedingWeekItems.add(child.id);
    } else {
      idsNeedingWeekItems.add(c.project.id);
    }
  }

  const wiByProject = new Map<string, WeekItemRow[]>();
  if (idsNeedingWeekItems.size > 0) {
    const all = await db
      .select()
      .from(weekItems)
      .where(inArray(weekItems.projectId, Array.from(idsNeedingWeekItems)));
    for (const w of all) {
      const pid = w.projectId;
      if (!pid) continue;
      const arr = wiByProject.get(pid);
      if (arr) arr.push(w);
      else wiByProject.set(pid, [w]);
    }
  }

  function hasContent(c: ClassifiedTop): boolean {
    if (c.kind === "wrapper") return true;
    return (wiByProject.get(c.project.id) ?? []).length > 0;
  }
  classified.sort((a, b) => {
    const ac = hasContent(a) ? 0 : 1;
    const bc = hasContent(b) ? 0 : 1;
    if (ac !== bc) return ac - bc;
    return a.project.name.localeCompare(b.project.name);
  });

  const sections: RundownSection[] = [];
  const overall: SeverityCounts = { ...ZERO };

  for (const c of classified) {
    if (c.kind === "wrapper") {
      const orphanItems = (wiByProject.get(c.project.id) ?? []).map((w) => ({
        id: w.id,
        title: w.title,
      }));
      const wrapperData = buildWrapperSectionData(
        c.project,
        client,
        c.children,
        orphanItems,
        generatedAt,
        todayISO,
      );
      sections.push({
        anchor: slugAnchor(c.project.name),
        kind: "wrapper",
        title: c.project.name,
        data: wrapperData,
      });
      addSeverity(overall, wrapperData.summary.severity);

      const sortedChildren = [...c.children].sort((a, b) =>
        a.name.localeCompare(b.name),
      );
      for (const child of sortedChildren) {
        const wis = wiByProject.get(child.id) ?? [];
        const relationship = detectChildProjectIssues(child, c.project);
        const extraChart = [...relationship.inline, ...relationship.subRow];
        const childData = buildL1SectionData(
          child,
          client,
          wis,
          todayISO,
          generatedAt,
          extraChart,
        );
        sections.push({
          anchor: slugAnchor(`${c.project.name}-${child.name}`),
          kind: "wrapper-child",
          title: child.name,
          parentTitle: c.project.name,
          data: childData,
        });
        addSeverity(overall, childData.summary.severity);
      }
    } else {
      const wis = wiByProject.get(c.project.id) ?? [];
      const data = buildL1SectionData(
        c.project,
        client,
        wis,
        todayISO,
        generatedAt,
      );
      sections.push({
        anchor: slugAnchor(c.project.name),
        kind: "standalone",
        title: c.project.name,
        data,
      });
      addSeverity(overall, data.summary.severity);
    }
  }

  return {
    client,
    sections,
    generatedAt,
    overallSeverity: overall,
  };
}

// ── GenerateGanttShare ────────────────────────────────────

export type GenerateGanttShareInput = {
  clientSlug: string;
  projectSlug?: string;
  theme: Theme;
  /**
   * Override the base URL for the share link.
   *
   * Fallback chain (Q1 amendment):
   *   1. input.origin — explicit caller override
   *   2. process.env.NEXT_PUBLIC_APP_URL — set in .env.local for dev/staging
   *   3. "https://runway.startround1.com" — hardcoded production default
   *
   * This lets dev and staging environments override the origin without code
   * changes by setting NEXT_PUBLIC_APP_URL in their respective env files.
   */
  origin?: string;
  /** TTL in days. Default: 7. */
  ttlDays?: number;
};

export type GenerateGanttShareResult = {
  shareUrl: string;
  expiresAt: string;
  summary: {
    kind: "client" | "project";
    clientName: string;
    projectName?: string;
    sectionCount?: number;
    rowCount?: number;
    severity: { critical: number; warn: number; info: number };
  };
};

/**
 * Generate a signed share URL for a Gantt view.
 *
 * Renders the requested view (client rundown or single-project triage) to
 * HTML, uploads it to R2 at `gantt-share/{nonce}/render.html`, and returns
 * the signed URL.
 *
 * Origin resolution (Q1 amendment):
 *   input.origin ?? process.env.NEXT_PUBLIC_APP_URL ?? "https://runway.startround1.com"
 *
 * Throws on:
 * - R2 not configured (`isR2Configured()` false)
 * - RUNWAY_SHARE_SECRET missing
 * - DB resolution failure (with available slugs in the error message)
 * - Render failure
 */
export async function generateGanttShare(
  input: GenerateGanttShareInput,
): Promise<GenerateGanttShareResult> {
  // Fail-fast: R2 must be configured before we do any DB work
  if (!isR2Configured()) {
    throw new Error(
      "R2 not configured. Set R2_ACCOUNT_ID, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY, and R2_BUCKET_NAME.",
    );
  }

  const db = getRunwayDb();
  const todayISO = new Date().toISOString().split("T")[0];
  const generatedAt = todayISO;

  // Resolve client
  const clientResult = await resolveClient(db, input.clientSlug);
  if (!clientResult.ok) {
    const available = clientResult.available?.join(", ") ?? "none";
    throw new Error(
      `Client not found: "${input.clientSlug}". Available: ${available}`,
    );
  }
  const { client, topLevelProjects } = clientResult;

  let html: string;
  let kind: "client" | "project";
  let projectName: string | undefined;
  let sectionCount: number | undefined;
  let rowCount: number | undefined;
  let severity: { critical: number; warn: number; info: number };

  if (input.projectSlug) {
    // Single-project triage
    const projectResult = await resolveProject(db, input.projectSlug);
    if (!projectResult.ok) {
      const available = projectResult.available?.join(", ") ?? "none";
      throw new Error(
        `Project not found: "${input.projectSlug}". Available: ${available}`,
      );
    }
    const { subject } = projectResult;

    // Assert project belongs to the requested client
    if (subject.project.clientId !== client.id) {
      throw new Error(
        `Project "${input.projectSlug}" does not belong to client "${input.clientSlug}".`,
      );
    }

    const rawData = await extractData(db, subject, client);
    const ganttData =
      rawData.kind === "wrapper"
        ? (() => {
            // Build wrapper gantt data inline
            const orphanItems = (rawData.orphanWeekItems ?? []).map((w) => ({
              id: w.id,
              title: w.title,
            }));
            return buildWrapperSectionData(
              subject.project,
              client,
              rawData.kind === "wrapper" ? rawData.children : [],
              orphanItems,
              generatedAt,
              todayISO,
            );
          })()
        : buildL1SectionData(
            subject.project,
            client,
            rawData.kind === "l1" ? rawData.children : [],
            todayISO,
            generatedAt,
          );

    html = renderGantt(ganttData, input.theme);
    kind = "project";
    projectName = subject.project.name;
    rowCount = ganttData.rows.length;
    severity = ganttData.summary.severity;
  } else {
    // Client rundown
    const rundownData = await extractClientRundown(
      db,
      client,
      topLevelProjects,
      generatedAt,
      todayISO,
    );
    html = renderClientRundown(rundownData, input.theme);
    kind = "client";
    sectionCount = rundownData.sections.length;
    rowCount = rundownData.sections.reduce((sum, s) => sum + s.data.rows.length, 0);
    severity = rundownData.overallSeverity;
  }

  // Build and sign token
  const nonce = crypto.randomBytes(6).toString("base64url");
  const payload = makePayload({
    kind,
    clientSlug: input.clientSlug,
    ...(input.projectSlug ? { projectSlug: input.projectSlug } : {}),
    theme: input.theme,
    ttlDays: input.ttlDays ?? 7,
  });
  // Override nonce with our pre-generated one for R2 key consistency
  const finalPayload = { ...payload, nonce };
  const token = signPayload(finalPayload);

  // Upload to R2
  const storageKey = `gantt-share/${nonce}/render.html`;
  await uploadContent(storageKey, html, "text/html; charset=utf-8", {
    "expires-at": finalPayload.expiresAt,
    "client-slug": input.clientSlug,
    kind,
    theme: input.theme,
  });

  // Build share URL (Q1 amendment: env-var fallback chain)
  const origin =
    input.origin ??
    process.env.NEXT_PUBLIC_APP_URL ??
    "https://runway.startround1.com";
  const shareUrl = `${origin}/api/runway/gantt-share/${token}`;

  return {
    shareUrl,
    expiresAt: finalPayload.expiresAt,
    summary: {
      kind,
      clientName: client.name,
      ...(projectName ? { projectName } : {}),
      ...(sectionCount !== undefined ? { sectionCount } : {}),
      ...(rowCount !== undefined ? { rowCount } : {}),
      severity,
    },
  };
}

/**
 * GET /api/runway/gantt-share/[token]
 *
 * Serves a pre-rendered HTML Gantt from R2 after verifying the HMAC token.
 *
 * Status codes:
 *   200 — valid token + R2 hit → HTML body
 *   404 — malformed/bad-signature/bad-version token OR R2 miss
 *   410 — expired token
 *   500 — R2 fetch threw unexpectedly
 *   405 — non-GET method
 *
 * Notes:
 * - NoIndex/NoFollow headers prevent search engine indexing.
 * - Cache-Control: private, max-age=300 allows browser caching only.
 * - OpenGraph meta tags intentionally omitted (operator Q2 confirmed SKIP).
 */

import { type NextRequest, NextResponse } from "next/server";
import { getContent } from "@/lib/storage/r2-client";
import { verifyToken } from "@/lib/runway/gantt/share-token";

export const dynamic = "force-dynamic";

export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ token: string }> },
): Promise<Response> {
  const { token } = await params;

  const verification = verifyToken(token);

  if (!verification.ok) {
    if (verification.reason === "expired") {
      return new Response("Share link expired", { status: 410 });
    }
    // malformed | bad-signature | bad-version → 404 (don't help attackers)
    return new Response(null, { status: 404 });
  }

  const { payload } = verification;
  const storageKey = `gantt-share/${payload.nonce}/render.html`;

  let html: string | null;
  try {
    html = await getContent(storageKey);
  } catch (err) {
    console.error("[gantt-share] R2 fetch failed:", err);
    return new Response("R2 fetch failed", { status: 500 });
  }

  if (html === null) {
    return new Response(null, { status: 404 });
  }

  return new Response(html, {
    status: 200,
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "private, max-age=300",
      "X-Robots-Tag": "noindex, nofollow",
    },
  });
}

export async function POST(): Promise<Response> {
  return NextResponse.json({ error: "Method not allowed" }, { status: 405 });
}

export async function DELETE(): Promise<Response> {
  return NextResponse.json({ error: "Method not allowed" }, { status: 405 });
}

/**
 * Unit tests for GET /api/runway/gantt-share/[token]
 *
 * Mocks: @/lib/storage/r2-client, @/lib/runway/gantt/share-token
 */

import { describe, it, expect, vi, beforeEach } from "vitest";

// Mock r2-client
const mockGetContent = vi.fn();
vi.mock("@/lib/storage/r2-client", () => ({
  getContent: mockGetContent,
}));

// Mock share-token
const mockVerifyToken = vi.fn();
vi.mock("@/lib/runway/gantt/share-token", () => ({
  verifyToken: mockVerifyToken,
}));

const VALID_PAYLOAD = {
  v: 1 as const,
  kind: "client" as const,
  clientSlug: "test-client",
  theme: "light-branded" as const,
  generatedAt: new Date().toISOString(),
  expiresAt: new Date(Date.now() + 86400_000).toISOString(),
  nonce: "abc12345",
};

function makeRequest(token: string) {
  return new Request(`http://localhost/api/runway/gantt-share/${token}`);
}

describe("GET /api/runway/gantt-share/[token]", () => {
  beforeEach(() => {
    vi.resetModules();
    mockGetContent.mockReset();
    mockVerifyToken.mockReset();
  });

  it("valid token + R2 hit → 200 with text/html content-type", async () => {
    mockVerifyToken.mockReturnValue({ ok: true, payload: VALID_PAYLOAD });
    mockGetContent.mockResolvedValue("<html>gantt</html>");

    const { GET } = await import("./route");
    const res = await GET(makeRequest("valid-token") as Parameters<typeof GET>[0], {
      params: Promise.resolve({ token: "valid-token" }),
    });

    expect(res.status).toBe(200);
    expect(res.headers.get("Content-Type")).toBe("text/html; charset=utf-8");
    const body = await res.text();
    expect(body).toBe("<html>gantt</html>");
  });

  it("valid token + R2 miss → 404", async () => {
    mockVerifyToken.mockReturnValue({ ok: true, payload: VALID_PAYLOAD });
    mockGetContent.mockResolvedValue(null);

    const { GET } = await import("./route");
    const res = await GET(makeRequest("valid-token") as Parameters<typeof GET>[0], {
      params: Promise.resolve({ token: "valid-token" }),
    });

    expect(res.status).toBe(404);
  });

  it("malformed token → 404", async () => {
    mockVerifyToken.mockReturnValue({ ok: false, reason: "malformed" });

    const { GET } = await import("./route");
    const res = await GET(makeRequest("bad") as Parameters<typeof GET>[0], {
      params: Promise.resolve({ token: "bad" }),
    });

    expect(res.status).toBe(404);
  });

  it("expired token → 410 with 'Share link expired' body", async () => {
    mockVerifyToken.mockReturnValue({ ok: false, reason: "expired" });

    const { GET } = await import("./route");
    const res = await GET(makeRequest("expired") as Parameters<typeof GET>[0], {
      params: Promise.resolve({ token: "expired" }),
    });

    expect(res.status).toBe(410);
    const body = await res.text();
    expect(body).toBe("Share link expired");
  });

  it("R2 throws non-null → 500", async () => {
    mockVerifyToken.mockReturnValue({ ok: true, payload: VALID_PAYLOAD });
    mockGetContent.mockRejectedValue(new Error("NoSuchBucket"));

    const { GET } = await import("./route");
    const res = await GET(makeRequest("valid-token") as Parameters<typeof GET>[0], {
      params: Promise.resolve({ token: "valid-token" }),
    });

    expect(res.status).toBe(500);
  });

  it("response includes X-Robots-Tag and Cache-Control headers on 200", async () => {
    mockVerifyToken.mockReturnValue({ ok: true, payload: VALID_PAYLOAD });
    mockGetContent.mockResolvedValue("<html>ok</html>");

    const { GET } = await import("./route");
    const res = await GET(makeRequest("valid-token") as Parameters<typeof GET>[0], {
      params: Promise.resolve({ token: "valid-token" }),
    });

    expect(res.status).toBe(200);
    expect(res.headers.get("X-Robots-Tag")).toBe("noindex, nofollow");
    expect(res.headers.get("Cache-Control")).toBe("private, max-age=300");
  });
});

